// === Tab: main.js ===
// SECTION 1: GLOBAL VARIABLES & PRELOAD
let hearts = [];
var imgs = [];
var imgNames = ["Pune street type 2-07.png"];
var imgIndex = -1;

var loadPercentage = 0.045; // 0 to 1.0
var closeEnoughTarget = 50;

var allParticles = [];

var mouseSizeSlider;
var particleSizeSlider;
var speedSlider;
var resSlider;
var nextImageButton;

function preload() {
  // Pre-load all images.
  for (var i = 0; i < imgNames.length; i++) {
    var newImg = loadImage(imgNames[i]);
    imgs.push(newImg);
  }
}


// SECTION 2: SETUP & DRAW

function setup() {
  createCanvas(windowWidth, windowHeight);

  // Create on-screen controls.
  mouseSizeSlider = new SliderLayout("Mouse size", 50, 200, 100, 1, 100, 100);
  particleSizeSlider = new SliderLayout("Particle size", 1, 20, 8, 1, 100, mouseSizeSlider.slider.position().y+70);
  speedSlider = new SliderLayout("Speed", 0, 5, 1, 0.5, 100, particleSizeSlider.slider.position().y+70);
  resSlider = new SliderLayout("Count multiplier (on next image)", 0.1, 2, 1, 0.1, 100, speedSlider.slider.position().y+70);
  nextImageButton = createButton("Next image");
  nextImageButton.position(100, resSlider.slider.position().y+40);
  nextImageButton.mousePressed(nextImage);

  // Change to first image.
  nextImage();
}

function draw() {
  background(0);

  for (var i = allParticles.length-1; i > -1; i--) {
    allParticles[i].move();
    allParticles[i].draw();

    if (allParticles[i].isKilled) {
      if (allParticles[i].isOutOfBounds()) {
        allParticles.splice(i, 1);
      }
    }
  }

  // Display slider labels.
  mouseSizeSlider.display();
  particleSizeSlider.display();
  speedSlider.display();
  resSlider.display();
}

function keyPressed() {
  nextImage();
}


// SECTION 3: IMAGE HANDLING & PARTICLES

function generateRandomPos(x, y, mag) {
  var pos = new p5.Vector(x, y);
  var randomDirection = new p5.Vector(random(width), random(height));
  var vel = p5.Vector.sub(randomDirection, pos);
  vel.normalize();
  vel.mult(mag);
  pos.add(vel);
  return pos;
}

function nextImage() {
  imgIndex++;
  if (imgIndex > imgs.length-1) {
    imgIndex = 0;
  }

  // Resize image to fit screen while maintaining aspect ratio
  let img = imgs[imgIndex];
  let aspectRatio = img.width / img.height;
  let targetWidth = min(windowWidth * 0.6, img.width);
  let targetHeight = targetWidth / aspectRatio;
  img.resize(floor(targetWidth), floor(targetHeight));
  img.loadPixels();

  let particleIndexes = [];
  for (let i = 0; i < allParticles.length; i++) {
    particleIndexes.push(i);
  }

  let pixelIndex = 0;
  for (let y = 0; y < img.height; y++) {
    for (let x = 0; x < img.width; x++) {
      let r = img.pixels[pixelIndex];
      let g = img.pixels[pixelIndex + 1];
      let b = img.pixels[pixelIndex + 2];
      pixelIndex += 4;

      if (random(1.0) > loadPercentage * resSlider.slider.value()) continue;

      let col = color(r, g, b);
      let newParticle;

      if (particleIndexes.length > 0) {
        let index = particleIndexes.splice(floor(random(particleIndexes.length)), 1);
        newParticle = allParticles[index];
      } else {
        newParticle = new Particle(width/2, height/2);
        allParticles.push(newParticle);
      }

      newParticle.target.x = x + width/2 - img.width/2;
      newParticle.target.y = y + height/2 - img.height/2;
      newParticle.endColor = col;
    }
  }

  for (let i = 0; i < particleIndexes.length; i++) {
    allParticles[particleIndexes[i]].kill();
  }
}


// SECTION 4: PARTICLE CLASS & SLIDER UI

function Particle(x, y) {
  this.pos = createVector(x, y);
  this.vel = createVector(0, 0);
  this.acc = createVector(0, 0);
  this.target = createVector(0, 0);
  this.isKilled = false;

  this.maxSpeed = random(0.25, 2);
  this.maxForce = random(8, 15);

  this.currentColor = color(0);
  this.endColor = color(0);
  this.colorBlendRate = random(0.01, 0.05);
  this.currentSize = 0;
  this.distToTarget = 0;

  this.move = function() {
    this.distToTarget = dist(this.pos.x, this.pos.y, this.target.x, this.target.y);
    let proximityMult = this.distToTarget < closeEnoughTarget ? this.distToTarget / closeEnoughTarget : 1;
    this.vel.mult(this.distToTarget < closeEnoughTarget ? 0.9 : 0.95);

    if (this.distToTarget > 1) {
      let steer = p5.Vector.sub(this.target, this.pos);
      steer.normalize();
      steer.mult(this.maxSpeed * proximityMult * speedSlider.slider.value());
      this.acc.add(steer);
    }

    let mouseDist = dist(this.pos.x, this.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    if (mouseDist < mouseSizeSlider.slider.value()) {
      let push = ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))
        ? p5.Vector.sub(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), this.pos)
        : p5.Vector.sub(this.pos, createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
      push.normalize();
      push.mult((mouseSizeSlider.slider.value() - mouseDist) * 0.05);
      this.acc.add(push);
    }

    this.vel.add(this.acc);
    this.vel.limit(this.maxForce * speedSlider.slider.value());
    this.pos.add(this.vel);
    this.acc.mult(0);
  }

  this.draw = function() {
    this.currentColor = lerpColor(this.currentColor, this.endColor, this.colorBlendRate);
    stroke(this.currentColor);
    let targetSize = this.isKilled ? 2 : map(min(this.distToTarget, closeEnoughTarget), closeEnoughTarget, 0, 0, particleSizeSlider.slider.value());
    this.currentSize = lerp(this.currentSize, targetSize, 0.1);
    strokeWeight(this.currentSize);
    point(this.pos.x, this.pos.y);
  }

  this.kill = function() {
    if (!this.isKilled) {
      this.target = generateRandomPos(width/2, height/2, max(width, height));
      this.endColor = color(0);
      this.isKilled = true;
    }
  }

  this.isOutOfBounds = function() {
    return this.pos.x < 0 || this.pos.x > width || this.pos.y < 0 || this.pos.y > height;
  }
}

function SliderLayout(label, minValue, maxValue, defaultValue, steps, posx, posy) {
  this.label = label;
  this.slider = createSlider(minValue, maxValue, defaultValue, steps);
  this.slider.position(posx, posy);

  this.display = function() {
    let sliderPos = this.slider.position();
    noStroke();
    fill(0);
    textSize(15);
    text(this.label, sliderPos.x, sliderPos.y - 10);
    text(this.slider.value(), sliderPos.x + this.slider.width + 10, sliderPos.y + 10);
  }
}

//HEART CLASS
class Heart {
  constructor() {
    this.x = random(width);
    this.y = random(height);
    this.size = random(6, 14);
    this.speed = random(0.3, 1.2);
    this.alpha = random(120, 200);
  }

  update() {
    this.y -= this.speed;
    if (this.y < -10) {
      this.y = height + 10;
      this.x = random(width);
    }
  }

  display() {
    fill(255, 105, 180, this.alpha); // Blush pink
    noStroke();
    beginShape();
    vertex(this.x, this.y);
    bezierVertex(this.x - this.size / 2, this.y - this.size / 2,
                 this.x - this.size, this.y + this.size / 3,
                 this.x, this.y + this.size);
    bezierVertex(this.x + this.size, this.y + this.size / 3,
                 this.x + this.size / 2, this.y - this.size / 2,
                 this.x, this.y);
    endShape(CLOSE);
  }
}

